    std::vector<DocumentState> states(3,state);DocumentResources usage;for(const auto& s:states)AccountState(s,usage);AccountState(state,usage);usage.annotationBytes+=4*sizeof(DocumentState);
    check(HistoryRetentionStart(states,state,usage.Bytes(),20)==0,"shared history estimator accepts exact estimated boundary");check(HistoryRetentionStart(states,state,usage.Bytes()-1,20)==1,"annotation/vector storage contributes to retention budget");check(HistoryRetentionStart(states,state,0,20)==3,"one oversized immediate Undo survives");check(HistoryRetentionStart(states,state,SIZE_MAX,2)==2,"history retains configured count bound");
    auto heavy=state;heavy.objects[0].points.reserve(2000);DocumentResources lightUsage,heavyUsage;AccountState(state,lightUsage);AccountState(heavy,heavyUsage);check(heavyUsage.Bytes()>=lightUsage.Bytes()+2000*sizeof(POINT),"reserved path capacity is included in storage estimate");check(heavyUsage.imageBytes==sizeof(Image)+state.base->pixels.capacity(),"shared asset storage counted once");
    for(int phase=1;phase<=3;++phase){Document doc;doc.Reset(state);doc.Add(a);doc.Undo();const auto base=doc.State().base;documentCommitFault=phase;bool rejected=false;try{doc.Add(a);}catch(const std::bad_alloc&){rejected=true;}documentCommitFault=0;check(rejected&&doc.State().base==base&&doc.UndoCount()==0&&doc.RedoCount()==1,"allocation fault preserves document and both history stacks");}
