void Clipboard(Check check){using namespace sct::services;uint32_t sequence=100;ClipboardSequenceAudit generation([&]{return sequence;});int empties=0,closes=0,sets=0;bool changeOpen=false,changeClose=false,partial=false,busy=false;
    ClipboardApi api;api.sequence=[&]{return sequence;};api.open=[&](HWND){if(changeOpen)++sequence;return !busy;};api.empty=[&]{++empties;++sequence;return true;};api.set=[&](UINT format,HGLOBAL handle){++sets;if(partial&&format!=CF_DIB)return false;GlobalFree(handle);++sequence;return true;};api.close=[&]{++closes;if(changeClose)++sequence;};ClipboardApiAudit sink(api);CString error;ClipboardPublication receipt;
    auto packet=PrepareClipboardImage(Pixels(),error);auto ticket=BeginClipboardTransfer();const auto expected=PendingClipboardSequence(ticket);changeOpen=true;check(!PublishClipboardImage(*packet,nullptr,error,nullptr,&receipt,expected)&&receipt.superseded&&empties==0&&sets==0&&closes==1&&packet->dib&&packet->png,"generation changed while opening cannot empty or overwrite external clipboard");CompleteClipboardTransfer(ticket,false);changeOpen=false;
    ticket=BeginClipboardTransfer();changeClose=true;check(PublishClipboardImage(*packet,nullptr,error,nullptr,&receipt,PendingClipboardSequence(ticket))&&receipt.sequence&&*receipt.sequence+1==sequence,"publication receipt captures generation before unlocking");CompleteClipboardTransfer(ticket,true,receipt.sequence);check(InspectClipboardTransfer(ticket)==ClipboardTransferState::Failed&&ClipboardTransferForPaste()==0,"post-close external copy cannot masquerade as our ready image");changeClose=false;
    packet=PrepareClipboardImage(Pixels(),error);ticket=BeginClipboardTransfer();partial=true;check(!PublishClipboardImage(*packet,nullptr,error,nullptr,&receipt,PendingClipboardSequence(ticket))&&receipt.imagePublished&&receipt.sequence&&!receipt.editablePublished,"partial raster publication has its own locked receipt");CompleteClipboardTransfer(ticket,true,receipt.sequence);check(InspectClipboardTransfer(ticket)==ClipboardTransferState::Ready,"partial raster remains pasteable at its exact generation");partial=false;
    packet=PrepareClipboardImage(Pixels(),error);ticket=BeginClipboardTransfer();const int before=empties;busy=true;bool isBusy=false;check(!PublishClipboardImage(*packet,nullptr,error,&isBusy,&receipt,PendingClipboardSequence(ticket))&&isBusy&&empties==before&&!receipt.sequence,"busy clipboard publishes nothing and can retry safely");busy=false;check(PublishClipboardImage(*packet,nullptr,error,&isBusy,&receipt,PendingClipboardSequence(ticket))&&receipt.sequence,"retry reuses prepared handles with original expected generation");CompleteClipboardTransfer(ticket,true,receipt.sequence);
}
