    core::DocumentState large;large.base=state.base;large.objects.resize(600);for(auto& a:large.objects)a.points.resize(256);p->document_.Reset(large);p->objectPreview_=large;p->objectGesture_=true;const auto start=std::chrono::steady_clock::now();for(int i=0;i<20;++i){auto old=p->document_.State();old=p->objectPreview_;if(old.objects.size()!=600)throw std::runtime_error("Snapshot baseline");}const auto middle=std::chrono::steady_clock::now();for(int i=0;i<20;++i){const auto one=p->RenderSnapshot(false);if(one.objects.size()!=600)throw std::runtime_error("Snapshot candidate");}const auto end=std::chrono::steady_clock::now();log<<"SNAPSHOT_US old="<<std::chrono::duration_cast<std::chrono::microseconds>(middle-start).count()<<" new="<<std::chrono::duration_cast<std::chrono::microseconds>(end-middle).count()<<" (observational only)\n";p->objectGesture_=false;
